      {data.kind === "module" && <ModuleDetails raw={data.raw} actions={data.grantedActions} />}
      {data.kind === "trigger" && <TriggerDetails raw={data.raw} />}
      {data.kind === "channel" && <ChannelDetails raw={data.raw} />}
